};
function swapCar(d){state.car=(state.car+d+cars.length)%cars.length;render.garage()}
function race(rank=false){screen(`<canvas id="track"></canvas><div class="hud"><div class="hudbox">POS <span id="pos">1</span>/6</div><div class="hudbox" id="time">00:00.00</div></div><div class="controls"><div class="pedals"><button class="ctrl" id="left">◀</button><button class="ctrl" id="right">▶</button></div><button class="ctrl go" id="gas">▲</button></div>`,'race');startRace(rank)}
function startRace(rank=false){const c=$('#track'),ctx=c.getContext('2d');let w=c.width=520,h=c.height=innerHeight;let player={x:260,y:h-150,spd:0,angle:0},others=[{x:210,z:650,color:'#fff'},{x:300,z:770,color:'#26c8d8'},{x:260,z:940,color:'#f0f0b5'}],start=performance.now(),playing=true,keys={};
 function button(id,k){let e=$('#'+id);e.onpointerdown=e=>{e.prevent();keys[k]=true};e.onpointerup=e=>{e.prevent();keys[k]=false};e.onpointercancel=e=>{keys[k]=false}}
 button('left','left');button('right','right');button('gas','gas');
 function loop(t){if(!playing)return;let dt=Math.min(32,t-(loop.old||t))/16.6;loop.old=t;if(keys.gas)player.spd=Math.min(17,player.spd+.25*dt);else player.spd=Math.max(0,player.spd-.11*dt);if(keys.left)player.angle-=.035*dt;if(keys.right)player.angle+=.035*dt;player.angle*=.94;player.x+=Math.sin(player.angle)*player.spd*.24*dt;player.x=Math.max(55,Math.min(w-55,player.x));ctx.fillStyle='#080912';ctx.fillRect(0,0,w,h);ctx.fillStyle='#161526';ctx.fillRect(0,0,w,h);for(let i=0;i<13;i++){let yy=((i*90-player.spd*t*.12)%1170)-250;ctx.fillStyle=i%2?'#25212c':'#1d1d28';ctx.beginPath();ctx.moveTo(w/2+(player.angle*20),yy);ctx.lineTo(w/2+220+(player.angle*20),yy+90);ctx.lineTo(w/2+220+(player.angle*20),yy+130);ctx.lineTo(w/2+(player.angle*20),yy+40);ctx.fill()}ctx.fillStyle='#242331';ctx.beginPath();ctx.moveTo(w/2-310,0);ctx.lineTo(w/2-95,h);ctx.lineTo(w/2+95,h);ctx.lineTo(w/2+310,0);ctx.fill();ctx.strokeStyle='#ff2aa1';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(w/2-310,0);ctx.lineTo(w/2-95,h);ctx.moveTo(w/2+310,0);ctx.lineTo(w/2+95,h);ctx.stroke();ctx.fillStyle='#dbdce4';for(let i=0;i<12;i++){let y=(i*100-(t*player.spd*.5)%1200)-200;if(y>-20&&y<h){ctx.fillRect(w/2-145+(i%2?188:0),y,14,55)}} others.forEach((o,i)=>{o.z-=player.spd*.7;if(o.z<80)o.z=900;o.z=Math.max(80,o.z);let sc=1-o.z/1000, yy=h-o.z*.28, xx=w/2+(o.x-260)*(1-sc*.5);ctx.fillStyle=o.color;ctx.fillRect(xx-18,yy-10,36,20);ctx.fillStyle='#111';ctx.fillRect(xx-22,yy+5,8,12);ctx.fillRect(xx+14,yy+5,8,12)});drawCar(ctx,player.x,player.y,player.angle);let sec=(t-start)/1000,$time=$('#time');$time.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(Math.floor(sec%60)).padStart(2,'0')}.${String(Math.floor((sec%1)*100)).padStart(2,'0')}`;if(sec>25){playing=false;finish(sec)}else requestAnimationFrame(loop)}requestAnimationFrame(loop)
}
function drawCar(ctx,x,y,a){ctx.save();ctx.translate(x,y);ctx.rotate(a*.18);ctx.fillStyle='#090a10';ctx.fillRect(-38,-10,76,58);ctx.fillStyle='#d72836';ctx.fillRect(-32,-18,64,54);ctx.fillRect(-40,-5,80,34);ctx.fillStyle='#ff6370';ctx.fillRect(-30,-17,60,8);ctx.fillStyle='#252936';ctx.fillRect(-22,-12,44,25);ctx.fillStyle='#08090d';ctx.fillRect(-38,26,14,18);ctx.fillRect(24,26,14,18);ctx.fillStyle='#fff1b5';ctx.fillRect(-30,8,9,5);ctx.fillRect(21,8,9,5);ctx.restore()}
function finish(sec){let position=1+Math.floor(Math.random()*3);screen(`<div class="finish-card"><div class="result panel"><div style="font-size:12px;color:#ff62ad">CORRIDA FINALIZADA</div><h2>P${position}º LUGAR</h2><div class="hudbox" style="display:inline-block;margin:10px">${format(sec)}</div><button class="btn primary" onclick="nav('ranked')" style="justify-content:center;margin-top:16px;text-align:center">CONTINUAR</button></div></div>`,'race')}
function format(s){return `00:${String(Math.floor(s)).padStart(2,'0')}.${String(Math.floor((s%1)*100)).padStart(2,'0')}`}
render.home();
